const incoming = $input.first().json
const r =
  incoming.body && typeof incoming.body === 'object'
    ? incoming.body
    : incoming

const first = (...names) => {
  for (const name of names) {
    const value = r[name]
    if (value !== undefined && value !== null && value !== '') return value

  }
  return undefined
}

const text = value => {
  if (Array.isArray(value)) value = value[0]

  if (value && typeof value === 'object') {
    value = value.name ?? value.value ?? value.id
  }

  return value === undefined || value === null
    ? ''
    : String(value).trim().replace(/\\_/g, '_')
}

const bool = (value, fallback = false) => {
  if (value === undefined || value === null || value === '') return fallback
  if (typeof value === 'boolean') return value

  return ['true', '1', 'yes', 'checked', 'on'].includes(
    String(value).toLowerCase()
  )
}

const number = (value, fallback) => {
  if (Array.isArray(value)) value = value[0]

  if (value && typeof value === 'object') {
    value = value.name ?? value.value ?? value.id
  }

  const parsed = Number(value)
  return Number.isFinite(parsed) ? parsed : fallback
}

const ids = value => {
  if (value === undefined || value === null || value === '') return []

  const raw = Array.isArray(value) ? value : String(value).split(',')

  return raw
    .map(item => {
      if (item && typeof item === 'object') {
        return (
          item.bisonId ??
          item.emailBisonId ??
          item['EmailBison Email ID'] ??
          item['EmailBison Email Id'] ??
          item['Email ID'] ??
          item.value ??
          item.id
        )
      }

      return item
    })
    .map(value => Number(value))
    .filter(Number.isFinite)
}

const countValue = value => {
  if (value === undefined || value === null || value === '') return 0
  if (Array.isArray(value)) return value.length

  if (value && typeof value === 'object') {
    value = value.count ?? value.value ?? value.name ?? 0
  }

  const parsed = Number(value)
  return Number.isFinite(parsed) ? parsed : 0
}

const recordId = text(
  first('recordId', 'Record ID', 'Airtable Record ID')
)

const campaignName = text(
  first('Name', 'Campaign Name')
)

const status = text(
  first('Campaign Status', 'Status')
)

const forceCreate = bool(
  first('forceCreate', 'Force Create', 'Force Launch'),
  false
)

// The Campaigns table stores the EmailBison campaign ID in body['ID'].
// Read that exact field only so unrelated ID fields cannot trigger the guard.
// A real EmailBison campaign ID is a positive number; blank/null/0 are empty.
const existingCampaignIdText = text(
  incoming.body && typeof incoming.body === 'object'
    ? incoming.body['ID']
    : undefined
)

const existingCampaignIdNumber = Number(existingCampaignIdText)

const existingCampaignId =
  Number.isFinite(existingCampaignIdNumber) && existingCampaignIdNumber > 0
    ? String(existingCampaignIdNumber)
    : ''

const apiKey = text(
  first(
    'EmailBison API (from Client)',
    'EmailBison API',
    'Bison API Key'
  )
)

if (!recordId || !recordId.startsWith('rec')) {
  throw new Error('A valid Airtable Campaign recordId is required.')
}

if (!campaignName) {
  throw new Error('Campaign Name/Name is required.')
}

if (!apiKey) {
  throw new Error('EmailBison API (from Client) is missing.')
}

if (existingCampaignId && !forceCreate) {
  throw new Error(
    'This Airtable campaign already has an EmailBison campaign ID. Use forceCreate only after confirming a deliberate duplicate.'
  )
}

if (
  status.toLowerCase() !== 'spintax generated' &&
  !forceCreate
) {
  throw new Error(
    'Campaign Status must be Spintax Generated before creating the EmailBison draft.'
  )
}

/*
 * Build the final sequence.
 */
const variants = []

for (let step = 1; step <= 4; step++) {
  const maxVariants = Math.max(
    1,
    Math.min(
      10,
      number(
        first(
          'Variants - Step ' + step,
          'Number of variants - Step ' + step,
          'Number of Variants - Step ' + step,
          'Variants Step ' + step
        ),
        1
      )
    )
  )

  const threadReply =
    step > 1 &&
    bool(
      first(
        'Thread Reply - Step ' + step,
        'Thread Reply Step ' + step,
        'Step ' + step + ' Thread Reply'
      ),
      false
    )

  const stepVariants = []

  for (let variant = 1; variant <= maxVariants; variant++) {
    const subjectNames = [
      'Campaign Email ' + step + ' Subject Version ' + variant,
      'Campaign Subject ' + step + ' Version ' + variant,
      'Campaign Email ' + step + ' Subject Spintax ' + variant,
      'Campaign Email ' + step + ' Subject',
    ]

    const bodyNames = [
      'Campaign Body ' + step + ' Version ' + variant,
      'Campaign Email ' + step + ' Body Spintax ' + variant,
      ...(variant === 1
        ? ['Campaign Email ' + step + ' Body']
        : []),
    ]

    const sourceStepOneVariant =
      variants[0]?.[variant - 1] ?? variants[0]?.[0]

    const sourceStepOneSubject = text(
      sourceStepOneVariant?.subject
    ).replace(/^(?:re:\s*)+/i, '')

    const subject =
      threadReply && sourceStepOneSubject
        ? sourceStepOneSubject
        : text(first(...subjectNames))

    const body = text(first(...bodyNames))

    if (!subject && !body && variant === 1) break
    if (!subject && !body && variant > 1) continue

    if (!subject || !body) {
      throw new Error(
        'Step ' +
          step +
          ' variant ' +
          variant +
          ' is missing its final validated subject or body.'
      )
    }

    stepVariants.push({
      subject,
      body,
      threadReply,
    })
  }

  if (stepVariants.length) {
    variants.push(stepVariants)
  }
}

if (!variants.length) {
  throw new Error(
    'No populated final sequence steps were found. Add validated copy to at least Step 1 before uploading.'
  )
}

/*
 * Resolve Direct versus Generic.
 *
 * Split campaigns can still use their suffix.
 * Single unsuffixed campaigns are also supported.
 */
const explicitOutputType = text(
  first(
    'outputType',
    'Output Type',
    'Campaign Output Type',
    'Lead Output Type',
    'Email Type'
  )
).toLowerCase()

const genericLeadCount = Math.max(
  0,
  countValue(
    first(
      'genericLeadCount',
      'Generic Lead Count',
      'Final Generic Lead Count',
      'Final Generic Count',
      'Final Generic Leads',
      'Generic Leads'
    )
  )
)

const directLeadCount = Math.max(
  0,
  countValue(
    first(
      'directLeadCount',
      'Direct Lead Count',
      'Final Direct Lead Count',
      'Final Direct Count',
      'Final Direct Leads',
      'Direct Leads'
    )
  )
)

const hasGenericSuffix =
  / - Generic Emails$/i.test(campaignName)

const hasDirectSuffix =
  / - Direct Emails$/i.test(campaignName)

let outputType

if (
  ['generic', 'generic email', 'generic emails'].includes(
    explicitOutputType
  )
) {
  outputType = 'generic'
} else if (
  [
    'direct',
    'direct email',
    'direct emails',
    'named',
    'named contacts',
  ].includes(explicitOutputType)
) {
  outputType = 'direct'
} else if (hasGenericSuffix) {
  outputType = 'generic'
} else if (hasDirectSuffix) {
  outputType = 'direct'
} else if (
  genericLeadCount > 0 &&
  directLeadCount === 0
) {
  outputType = 'generic'
} else if (
  directLeadCount > 0 &&
  genericLeadCount === 0
) {
  outputType = 'direct'
} else {
  // Unsuffixed single campaigns are valid and default to Direct.
  outputType = 'direct'
}

const outputIsGeneric = outputType === 'generic'

/*
 * Generic lists have no first name.
 * Remove the complete greeting instead of replacing it with "Hey there".
 */
if (outputIsGeneric) {
  const removeGenericGreeting = value =>
    value
      .replace(
        /^(?:hey|hi|hello)\s+\{FIRST_NAME\}\s*[,!:\-]?\s*(?:\r?\n)+/gim,
        ''
      )
      .replace(/\{FIRST_NAME\}/gi, '')
      .replace(/^[ \t]+/gm, '')
      .replace(/\n{3,}/g, '\n\n')
      .trim()

  for (const stepVariants of variants) {
    for (const copy of stepVariants) {
      copy.subject = removeGenericGreeting(copy.subject)
      copy.body = removeGenericGreeting(copy.body)

      if (
        /\{FIRST_NAME\}/i.test(
          copy.subject + '\n' + copy.body
        )
      ) {
        throw new Error(
          'Generic-email copy still contains {FIRST_NAME}.'
        )
      }
    }
  }
}

/*
 * Add the client signature.
 */
const clientCompanyName = text(
  first(
    'Client Company Name',
    'Client Name',
    'Company Name (from Client)',
    'Company (from Client)',
    'Client'
  )
)

const senderTitle = text(
  first(
    'Sender Title',
    'Sender Title (from Client)',
    'Sender Job Title',
    'Client Sender Title'
  )
)

const signatureEnabled = bool(
  first('Add Email Signature', 'Include Email Signature'),
  true
)

const psEnabled = bool(
  first('Add Default P.S.', 'Include Default P.S.'),
  true
)

const hasSignature = body =>
  /(?:^|\n)\s*--\s*(?:\n|$)|(?:^|\n)\s*(?:best|kind|warm) regards|(?:^|\n)\s*(?:sincerely|yours truly|best wishes|warm wishes|thank you|thanks)\s*,?\s*(?:\n|$)/i.test(
    body
  )

const hasPostscript = body =>
  /(?:^|\n)\s*p\s*\.\s*s\s*\.?\s*(?::|-)?\s*/i.test(body)

const signatureLines = [
  '--',
  '{Best regards|Kind regards|Warm regards|Sincerely|Thank you|Thanks|Yours truly|With best wishes|Best wishes|Warm wishes},',
  '{SENDER_FULL_NAME}',
  [senderTitle, clientCompanyName].filter(Boolean).join(', '),
].filter(Boolean)

for (const stepVariants of variants) {
  for (const copy of stepVariants) {
    const additions = []

    if (
      signatureEnabled &&
      !hasSignature(copy.body)
    ) {
      additions.push(signatureLines.join('\n'))
    }

    if (
      psEnabled &&
      !hasPostscript(copy.body)
    ) {
      additions.push(
        "{P.S.|P.s.|p.s.} or tell me to pound sand if you'd like.."
      )
    }

    if (additions.length) {
      copy.body =
        copy.body.replace(/\s+$/, '') +
        '\n\n' +
        additions.join('\n\n')
    }
  }
}

/*
 * Find merge tags used in the final sequence.
 */
const mergeTagPattern =
  /\{([A-Za-z][A-Za-z0-9_]*)\}/g

const requiredMergeTags = [
  ...new Set(
    variants.flatMap(step =>
      step.flatMap(copy => {
        const matches = []

        for (const content of [
          copy.subject,
          copy.body,
        ]) {
          let match

          while (
            (match = mergeTagPattern.exec(content)) !== null
          ) {
            matches.push(match[1])
          }

          mergeTagPattern.lastIndex = 0
        }

        return matches
      })
    )
  ),
]

const leadListId =
  ids(
    first(
      'emailBisonLeadListId',
      'EmailBison Lead List ID',
      'Bison Lead List ID',
      'Lead List ID'
    )
  )[0] ?? null

const projectSheetLink = text(
  first(
    'Project Google Sheet Link (from Lead List)',
    'Project Google Sheet Link',
    'Lead List Link'
  )
)

const spreadsheetId =
  (
    projectSheetLink.match(
      /\/spreadsheets\/d\/([a-zA-Z0-9_-]+)/
    ) || []
  )[1] || ''

const outputTab =
  outputType === 'generic'
    ? 'Final Generic'
    : 'Final Direct'

if (!spreadsheetId) {
  throw new Error(
    'Project Google Sheet Link from the linked Lead List is required.'
  )
}

const leadListCsvUrl =
  'https://sheets.googleapis.com/v4/spreadsheets/' +
  spreadsheetId +
  '/values/' +
  encodeURIComponent("'" + outputTab + "'!A:ZZ") +
  '?majorDimension=ROWS'

const leadListCsvName =
  text(
    first(
      'leadListCsvName',
      'Lead List CSV Name',
      'CSV Attachment Name'
    )
  ) ||
  campaignName + '.csv'

const leadListName =
  text(first('leadListName', 'Lead List Name')) ||
  campaignName + ' Leads'

const senderEmailIds = ids(
  first(
    'EmailBison Sender Email IDs',
    'EmailBison Email IDs (from Email Accounts)',
    'EmailBison Email ID (from Email Accounts)',
    'Bison Sender Email IDs',
    'Sender Email IDs',
    'Email Account IDs'
  )
)

const rawClientContext = first('clientFields')

const clientContext =
  rawClientContext &&
  typeof rawClientContext === 'object'
    ? rawClientContext
    : {}

const linkedinEnabled = bool(
  first(
    'LinkedIn (from Client)',
    'LinkedIn',
    'LinkedIn Package'
  ) ??
    clientContext['LinkedIn (from Client)'] ??
    clientContext.LinkedIn ??
    clientContext['LinkedIn Package'] ??
    clientContext.fldkcU05DfpslNctF,
  false
)

const existingHeyReachCampaignId = number(
  first(
    'HeyReach Campaign ID',
    'Campaign ID (from LinkedIn Campaigns)'
  ),
  null
)

const shouldCreateHeyReach =
  outputType === 'direct' && linkedinEnabled

const rawSenderAccountLinks = first(
  'Email Accounts',
  'Sender Accounts'
)

const senderAccountRecordIds = (
  Array.isArray(rawSenderAccountLinks)
    ? rawSenderAccountLinks
    : [rawSenderAccountLinks]
)
  .map(item =>
    item && typeof item === 'object'
      ? item.id
      : item
  )
  .map(value =>
    value === undefined || value === null
      ? ''
      : String(value).trim()
  )
  .filter(value =>
    /^rec[a-zA-Z0-9]{14}$/.test(value)
  )

return [
  {
    json: {
      recordId,
      campaignName,
      status,
      forceCreate,
      apiKey,

      baseUrl:
        text(
          first(
            'EmailBison Base URL',
            'Bison Base URL'
          )
        ) || 'https://send.dulcy.io',

      campaignType:
        text(first('Campaign Type')) || 'outbound',

      variants,

      delayDays: Math.max(
        0,
        number(first('Days Between Emails'), 2)
      ),

      schedule: {
        monday: bool(first('Run on Monday'), true),
        tuesday: bool(first('Run on Tuesday'), true),
        wednesday: bool(
          first('Run on Wednesday'),
          true
        ),
        thursday: bool(
          first('Run on Thursday'),
          true
        ),
        friday: bool(first('Run on Friday'), true),
        saturday: bool(
          first('Run on Saturday'),
          false
        ),
        sunday: bool(first('Run on Sunday'), false),

        start_time:
          text(first('start_time', 'Start Time')) ||
          '09:00',

        end_time:
          text(first('end_time', 'End Time')) ||
          '17:00',

        timezone:
          text(first('TimeZone', 'Time Zone')) ||
          'America/New_York',

        save_as_template: bool(
          first(
            'save_as_template',
            'Save as Template'
          ),
          false
        ),
      },

      settings: {
        name: campaignName,

        max_emails_per_day: number(
          first(
            'max_emails_per_day',
            'Max Emails Per Day'
          ),
          1000
        ),

        max_new_leads_per_day: number(
          first(
            'max_new_leads_per_day',
            'Max New Leads Per Day'
          ),
          1000
        ),

        plain_text: bool(
          first('plain_text', 'Plain Text'),
          false
        ),

        open_tracking: bool(
          first('open_tracking', 'Open Tracking'),
          false
        ),

        reputation_building: bool(
          first(
            'reputation_building',
            'Reputation Building'
          ),
          false
        ),

        can_unsubscribe: bool(
          first(
            'can_unsubscribe',
            'Can Unsubscribe'
          ),
          false
        ),

        unsubscribe_text: text(
          first(
            'unsubscribe_text',
            'Unsubscribe Text'
          )
        ),
      },

      leadListId,
      leadListCsvUrl,
      leadListCsvName,
      leadListName,
      senderEmailIds,
      senderAccountRecordIds,

      senderDailyLimit: Math.max(
        1,
        number(
          first(
            'Sender Daily Limit',
            'Email Daily Limit',
            'email_daily_limit'
          ),
          10
        )
      ),

      requiredMergeTags,
      outputType,
      outputTab,
      spreadsheetId,
      clientCompanyName,
      linkedinEnabled,
      shouldCreateHeyReach,
      clientContext,
      existingHeyReachCampaignId,

      setupWarnings: [
        !leadListId && !leadListCsvUrl
          ? 'No EmailBison lead-list ID or CSV attachment was supplied leads were not attached.'
          : null,

        !senderEmailIds.length
          ? 'No numeric EmailBison Sender Email IDs were supplied sender accounts were not attached.'
          : null,

        signatureEnabled && !clientCompanyName
          ? 'No linked Airtable client name was supplied, so the signature contains TITLE without a company name.'
          : null,
      ].filter(Boolean),
    },
  },
]

const c = $('Normalize and Validate Campaign').first().json;
const sequence_steps = [];
for (let stepIndex = 0; stepIndex < c.variants.length; stepIndex++) {
  const order = stepIndex + 1;
  // EmailBison stores the delay on the step that comes before the wait. A value
  // of 2 on Step 1 means: send Step 1, wait two days, then send Step 2.
  const wait = Math.max(1, c.delayDays);
  c.variants[stepIndex].slice(0, 1).forEach(copy => {
    const item = {
      email_subject: copy.subject,
      email_body: copy.body.replace(/\r?\n/g, '<br>'),
      order,
      wait_in_days: wait,
      variant: false,
      thread_reply: copy.threadReply,
    };
    sequence_steps.push(item);
  });
}
return [{json: {title: c.campaignName + ' Sequence', sequence_steps}}];

const c = $('Normalize and Validate Campaign').first().json;

const responseItems = $('Get Created Sequence Steps').all().map(item => item.json);

const unwrapSteps = value => {
  if (Array.isArray(value)) return value;
  if (Array.isArray(value?.data?.sequence_steps)) return value.data.sequence_steps;
  if (Array.isArray(value?.data)) return value.data;
  if (Array.isArray(value?.sequence_steps)) return value.sequence_steps;
  if (value?.id != null && value?.order != null) return [value];
  if (value?.data?.id != null && value.data.order != null) return [value.data];
  return [];
};

const createdSteps = responseItems.flatMap(unwrapSteps);
const primaryByOrder = new Map(
  createdSteps
    .filter(step => step && step.variant !== true && step.id != null)
    .map(step => [Number(step.order), Number(step.id)])
    .filter(([order, id]) => Number.isInteger(order) && Number.isInteger(id))
);

const output = [];
const steps = Array.isArray(c.variants) ? c.variants : [];

for (let stepIndex = 0; stepIndex < steps.length; stepIndex++) {
  const order = stepIndex + 1;
  const primaryId = primaryByOrder.get(order);
  const variants = Array.isArray(steps[stepIndex]) ? steps[stepIndex] : [];
  const extraVariants = variants.slice(1);

  if (extraVariants.length && !primaryId) {
    throw new Error(`EmailBison did not return a numeric primary sequence-step ID for Step ${order}.`);
  }

  for (const copy of extraVariants) {
    output.push({
      json: {
        hasVariants: true,
        stepOrder: order,
        payload: {
          title: `${c.campaignName} Step ${order} Variant`,
          sequence_steps: [{
            email_subject: copy.subject,
            email_body: String(copy.body ?? '').replace(/\r?\n/g, '<br>'),
            order,
            wait_in_days: Math.max(1, Number(c.delayDays) || 1),
            variant: true,
            variant_from_step_id: primaryId,
            thread_reply: Boolean(copy.threadReply),
          }],
        },
      },
    });
  }
}

return output.length ? output : [{json:{hasVariants:false,payload:null}}];

const c = $('Normalize and Validate Campaign').first().json;
const input = $input.first();
const googleRows = Array.isArray(input.json?.values) ? input.json.values : null;
let source = '';
let delimiter = ',';
if (!googleRows) {
  const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  source = buffer.toString('utf8').replace(/^\uFEFF/, '');
  const firstLine = source.split(/\r?\n/, 1)[0] || '';
  delimiter = (firstLine.match(/\t/g) || []).length > (firstLine.match(/,/g) || []).length ? '\t' : ',';
}
const parse = text => {
  const rows = []; let row = []; let cell = ''; let quoted = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (ch === '"') {
      if (quoted && text[i + 1] === '"') { cell += '"'; i++; }
      else quoted = !quoted;
    } else if (ch === delimiter && !quoted) { row.push(cell); cell = ''; }
    else if ((ch === '\n' || ch === '\r') && !quoted) {
      if (ch === '\r' && text[i + 1] === '\n') i++;
      row.push(cell); if (row.some(value => value !== '')) rows.push(row); row = []; cell = '';
    } else cell += ch;
  }
  row.push(cell); if (row.some(value => value !== '')) rows.push(row);
  return rows;
};
const rows = googleRows || parse(source);
if (rows.length < 2) throw new Error('The attached CSV has no lead rows.');
const headers = rows[0].map(value => value.trim());
const key = value => String(value || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const findIndexes = aliases => headers.map((header, index) => aliases.includes(key(header)) ? index : -1).filter(index => index >= 0);
const indexes = {
  first_name: findIndexes(['firstname','first','name']), last_name: findIndexes(['lastname','last']),
  email: findIndexes(['email','emails','emailaddress']), company: findIndexes(['company','companyname','businessname']),
  title: findIndexes(['title','jobtitle']),
  PHONE: findIndexes(['phone','phones','phonenumber']), IDEAS: findIndexes(['ideas','idea']),
  LINKEDIN: findIndexes(['linkedin','linkedinsocial','social','socialurl','socialurls','linkedinurl']),
  COLLEAGUE: findIndexes(['colleague','college']),
  CITY: findIndexes(['city']), CONTRACTOR: findIndexes(['contractor','contractortype']),
  CASESTUDY: findIndexes(['casestudy','case']), RESULT: findIndexes(['result','results']),
  ICP: findIndexes(['icp','idealcustomerprofile']), ICE: findIndexes(['ice']), FUND: findIndexes(['fund']),
  CONTACTS: findIndexes(['contacts']), LEADS: findIndexes(['leads']), PERSONAL: findIndexes(['personal']),
  RESTAURANT: findIndexes(['restaurant','restaurantname']),
  SENDSPARK1: findIndexes(['sendspark1']), SENDSPARK2: findIndexes(['sendspark2']), SENDSPARK3: findIndexes(['sendspark3']),
  Domain: findIndexes(['domain','website']),
};

// Any merge tag used by the approved copy can become a custom variable without
// another workflow edit. SERVICE_AREA, Service Area, and service_area all match.
const builtInMergeTags = new Set(['FIRST_NAME','LAST_NAME','COMPANY','EMAIL','TITLE','SENDER_FULL_NAME']);
const knownAliases = {
  LINKEDIN: ['linkedin','linkedinsocial','social','socialurl','socialurls','linkedinurl'],
  COLLEAGUE: ['colleague','college'], PHONE: ['phone','phones','phonenumber'],
  CITY: ['city'], CONTRACTOR: ['contractor','contractortype'], RESTAURANT: ['restaurant','restaurantname'],
};
for (const rawTag of c.requiredMergeTags || []) {
  const variableName = String(rawTag || '').trim();
  if (!variableName || builtInMergeTags.has(variableName.toUpperCase())) continue;
  const aliases = knownAliases[variableName.toUpperCase()] || [key(variableName)];
  const matches = findIndexes(aliases);
  if (matches.length) indexes[variableName] = matches;
}
const value = (row, candidates) => candidates.map(index => String(row[index] ?? '').trim()).find(Boolean) || '';
// Do not create or map custom variables whose source column is missing.
const deniedCustomVariableHeaders = new Set([
  'seniority','department','verified','connections','similarity','industrygroups',
  'score','employees','country','startdate','street','state','zip','redirectdomain',
  'mxprovider','description','keywords','updatedate','businessmodel','revenuerange',
]);
const requiredDeniedTags = (c.requiredMergeTags || []).filter(tag =>
  deniedCustomVariableHeaders.has(key(tag)),
);
if (requiredDeniedTags.length) {
  throw new Error(
    'Approved copy references denied lead-list variables: ' +
    requiredDeniedTags.join(', ') +
    '. Remove those merge tags or explicitly allow them before uploading.',
  );
}
