// A default of 10 is used only for direct numeric sender IDs that have no
// linked Email Account row in the webhook path.
const defaultDailyLimit = Math.max(1, Number(c.senderDailyLimit || 10));
const fetchedLimitsById = new Map();
for (const item of accountItems) {
  const id = Number(read(item.json, ['Email ID', 'EmailBison Email ID', 'EmailBison Email Id']));
  const rawLimit = read(item.json, [
    'email_daily_limit', 'Email Daily Limit', 'Cold Daily Limit',
    'Daily Limit', 'daily_limit',
  ]);
  const parsedLimit = Number(rawLimit);
  if (Number.isFinite(id) && id > 0) {
    fetchedLimitsById.set(id, Number.isFinite(parsedLimit) && parsedLimit > 0 ? parsedLimit : defaultDailyLimit);
  }
}

const senderLimits = senderEmailIds.map(id => ({
  id,
  dailyLimit: fetchedLimitsById.get(id) || defaultDailyLimit,
}));
const selectedDailyCapacity = senderLimits.reduce((sum, sender) => sum + sender.dailyLimit, 0);

const verifiedLeadCount = Number(
  $('Confirm Campaign Leads Attached').first().json.campaignLeadCount ??
  $('Normalize Lead List CSV').first().json.acceptedRows ??
  0,
);
