const sequenceStepCount = Array.isArray(c.variants) ? c.variants.length : 0;
const firstFollowupDelayDays = sequenceStepCount > 1 ? Math.max(1, Number(c.delayDays || 1)) : 1;
const safeDailyCapacity = Math.max(1, Math.floor(verifiedLeadCount / firstFollowupDelayDays));

